{
  "iteration": 1,
  "pcvs": [
    {
      "name": "batch_size",
      "expression": "len(output_token_ids)",
      "rationale": "Captures per-row list conversion, padding, and penalty setup."
    },
    {
      "name": "logit_elements",
      "expression": "logits.numel()",
      "rationale": "Measures the dense vocabulary-wide work of applying penalties."
    },
    {
      "name": "prompt_elements",
      "expression": "prompt_token_ids.numel()",
      "rationale": "Captures prompt-token processing for repetition penalties."
    },
    {
      "name": "padded_output_elements",
      "expression": "len(output_token_ids) * max(map(len, output_token_ids), default=0)",
      "rationale": "Measures the output tensor size governing padding, placeholder replacement, and output-token scatter work."
    }
  ],
  "hypothesis": "Instruction count combines fixed tensor-operation overhead with per-row conversion work and work proportional to logits, prompt tokens, and padded output tokens."
}
